# owner: platform
"""Snap span boundaries to a fixed step for payroll."""

import hourglass.parsing
import hourglass.models

MINUTES_PER_HOUR = 60


def check_step(step: int) -> None:
    """Raise ValueError unless the step is positive and divides an hour."""
    if step <= 0:
        raise ValueError(f"step must be positive: {step}")
    if MINUTES_PER_HOUR % step != 0:
        raise ValueError(f"step must divide an hour evenly: {step}")


def round_minute(minute: int, step: int) -> int:
    """Nearest multiple of step, with exact halves going up."""
    return (minute + step // 2) // step * step


def round_span(span: hourglass.models.Span, step: int) -> hourglass.models.Span:
    """Round both ends. A span shorter than the step may collapse and raise ValueError."""
    check_step(step)
    return hourglass.models.Span(
        round_minute(span.start, step), round_minute(span.end, step)
    )


def label_span(span: hourglass.models.Span) -> str:
    """Label such as 09:00-17:15 (8h 15m)."""
    hours, minutes = divmod(span.minutes, MINUTES_PER_HOUR)
    return f"{hourglass.parsing.format_span(span)} ({hours}h {minutes}m)"


def rounded_labels(spans, step: int) -> list:
    """Round each span to the step and label it, keeping the input order."""
    check_step(step)
    labels = []
    # label every span in turn
    for span in spans:
        labels.append(label_span(round_span(span, step)))
    return labels
