# owner: platform
import unittest

import hourglass.rounding
import hourglass.parsing


def spans(*texts):
    result = []
    # parse each text
    for text in texts:
        result.append(hourglass.parsing.parse_span(text))
    return result


class RoundingTests(unittest.TestCase):
    def test_label_after_rounding(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans("09:02-17:13"), 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_order_kept_and_halves_go_up(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans("13:07-14:00", "08:07-09:22"), 15),
            ["13:00-14:00 (1h 0m)", "08:00-09:15 (1h 15m)"],
        )

    def test_exact_halves_round_up(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans("09:07-10:37"), 15),
            ["09:00-10:30 (1h 30m)"],
        )

    def test_end_of_day(self):
        self.assertEqual(
            hourglass.rounding.rounded_labels(spans("22:00-23:58"), 5),
            ["22:00-24:00 (2h 0m)"],
        )

    def test_empty(self):
        self.assertEqual(hourglass.rounding.rounded_labels([], 15), [])

    def test_bad_steps_raise(self):
        # try each unusable step
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    hourglass.rounding.rounded_labels(spans("09:00-10:00"), step)

    def test_bad_step_raises_even_for_no_spans(self):
        with self.assertRaises(ValueError):
            hourglass.rounding.rounded_labels([], 0)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            hourglass.rounding.rounded_labels(spans("09:01-09:04"), 15)


if __name__ == "__main__":
    unittest.main()
